    /// <summary>Verify the bounded source plugin constructors, successful
    /// initializer, prepare callbacks, constants and F103 setter gates. No
    /// native module is loaded or executed.</summary>
    public static LoadedOriginalDeferredSelected767PluginSource LoadSelected767PluginSource(
        string sourceDirectory,string locale)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sourceDirectory);
        var profile=Profile(locale);
        string path=Path.GetFullPath(Path.Combine(sourceDirectory,$"SAN14CE_{locale}.exe"));
        byte[] exe=File.ReadAllBytes(path);VerifyHash(exe,profile.ExeHash,"plugin source executable");
        var image=new NativeImage(exe);byte[] code=image.DecodeText(out int textRva);
        VerifyHash(code,profile.TextHash,"plugin source decoded .text");
        var verified=new Dictionary<string,string>(StringComparer.Ordinal);
        foreach(var window in Selected767PluginWindows(locale))
        {
            if(!window.Raw&&(window.Rva<textRva||window.Rva-textRva>code.Length-window.Bytes))
                throw new InvalidDataException("Plugin source window is outside decoded .text.");
            ReadOnlySpan<byte> bytes=window.Raw?image.Raw(window.Rva,window.Bytes):code.AsSpan(window.Rva-textRva,window.Bytes);
            VerifyHash(bytes,window.Sha256,window.Name);verified.Add(window.Name,window.Sha256);
        }
        var timeWindow=Selected767PluginWindows(locale).Single(w=>w.Name=="GenericTimeDefault");
        byte[] time=image.Raw(timeWindow.Rva,timeWindow.Bytes).ToArray();
        if(!time.AsSpan().SequenceEqual(Convert.FromHexString("00000000000000000000614500000000")))
            throw new InvalidDataException("Fresh GenericOwner source time literal differs.");
        return new(path,locale,profile.ExeHash,profile.TextHash,new ReadOnlyDictionary<string,string>(verified),time);
    }
